const MAX_VISIBLE_COUNT = 99;

type CartBadgeProps = {
  count: number;
};

export function CartBadge({ count }: CartBadgeProps) {
  const visibleCount = count > MAX_VISIBLE_COUNT ? `${MAX_VISIBLE_COUNT}+` : String(count);

  if (count <= 0) {
    return null;
  }

  return (
    <span className="cart-badge" role="status" aria-label={`Items in cart: ${visibleCount}`}>
      {visibleCount}
    </span>
  );
}

